// KEVOS® Tools input guides: handbook6. What each input means, how to get it right and which figure explains it.
// Read with public/tools/input-guides.js; units, accepted ranges and examples come from data-handbook6.js.
window.WORKOS_INPUTS = Object.assign(window.WORKOS_INPUTS || {}, {
  'bolt-torque-preload': {
    mode: { what: 'Which way round the relation is solved: the torque needed to reach a preload set as a share of proof load, or the preload a known tightening torque produces.', tip: 'In torque mode the tightening torque input is ignored; in preload mode the target percentage is ignored.', fig: 'choice' },
    d: { what: 'The nominal (major) diameter of the bolt thread, the number after the M in the size designation. It sets the stress area and the lever arm in the torque relation.', tip: 'Use the thread size, not the shank diameter of a reduced-shank bolt or the hole size.', effect: 'For the same preload the torque rises in proportion to the diameter.', fig: 'diameter', sym: 'd' },
    P: { what: 'The axial distance from one thread crest to the next, the number after the × in a designation such as M12 × 1.75. It is used only to work out the tensile stress area.', tip: 'Coarse and fine threads of the same size have different pitches; a plain M designation without a pitch means the coarse series.', effect: 'A finer pitch gives a larger stress area, so a higher proof load.', fig: 'thread', sym: 'P' },
    K: { what: 'The nut factor: an empirical coefficient that lumps thread friction, under-head friction and geometry into one number linking torque to preload. It depends on plating, lubricant and surface condition.', tip: 'Take it from the fastener supplier for the actual finish and lubricant, or measure it with a torque–tension test; a lubricated bolt has a lower K than a dry one.', effect: 'Torque for a given preload rises in proportion to K; preload from a given torque falls as K rises.', fig: 'factor', sym: 'K' },
    Sp: { what: 'The proof strength (proof stress) of the bolt: the stress it must carry without permanent set, set by its property class. Multiplied by the stress area it gives the proof load.', tip: 'Use the proof stress for the property class in ISO 898-1 or the supplier’s data, not the tensile or yield strength.', effect: 'A higher proof strength raises the proof load, so the target preload and torque in torque mode.', fig: 'stress', sym: 'Sp' },
    pct: { what: 'The preload you want to reach, expressed as a share of the bolt’s proof load, chosen in your joint design. Used only in torque mode.', tip: 'Type the percentage itself, not a fraction. A value over 100 means loading the bolt past its proof load.', effect: 'Preload and tightening torque rise in proportion.', fig: 'percent' },
    T: { what: 'The tightening torque applied to the nut or bolt head, as specified on the drawing or set on the torque tool. Used only in preload mode to find the resulting preload.', tip: 'Make sure the value is in newton metres; a torque wrench set in ft·lbf or in·lbf must be converted first.', effect: 'Preload rises in proportion to torque.', fig: 'torque', sym: 'T' },
  },
  'thread-engagement': {
    d: { what: 'The basic major diameter of the thread, the nominal size in the designation. With the pitch it gives the basic pitch and minor diameters and the stress area.', tip: 'Enter the thread size, not the tap drill or the clearance hole size.', fig: 'thread', sym: 'd' },
    P: { what: 'The axial distance from one thread crest to the next. For a unified thread it is 25.4 divided by the threads per inch.', tip: 'Do not enter threads per inch here; convert TPI to a pitch in millimetres first.', fig: 'thread', sym: 'P' },
    Knmax: { what: 'The largest allowed minor diameter of the tapped (internal) thread for its tolerance class, from the thread limits table. It sets the shear area of the bolt thread.', tip: '0 uses the basic minor diameter, which gives a slightly optimistic, shorter engagement length.', fig: 'thread', sym: 'Kn' },
    Esmin: { what: 'The smallest allowed pitch diameter of the bolt (external) thread for its tolerance class, from the thread limits table. It sets the bolt thread shear area.', tip: '0 uses the basic pitch diameter. For very high-strength screws the tool also uses this value to work out the stress area.', fig: 'thread', sym: 'Es' },
    Dsmin: { what: 'The smallest allowed major diameter of the bolt (external) thread for its tolerance class. It sets the shear area of the tapped (internal) thread.', tip: '0 uses the basic major diameter; real bolts are slightly smaller, so a class limit gives a safer result.', fig: 'thread', sym: 'Ds' },
    Enmax: { what: 'The largest allowed pitch diameter of the tapped (internal) thread for its tolerance class. With the bolt major diameter it sets the internal thread shear area.', tip: '0 uses the basic pitch diameter. Enter all four class limits for a design check; the tool flags results that used basic sizes.', fig: 'thread', sym: 'En' },
    Sub: { what: 'The minimum tensile strength of the screw or bolt material, from its property class or material specification.', tip: 'Use the minimum ultimate tensile strength, not the proof or yield strength.', effect: 'A stronger screw raises the strength ratio J, so a longer engagement is needed when the tapped material governs.', fig: 'stress', sym: 'Su' },
    Sun: { what: 'The minimum tensile strength of the nut or of the part the thread is tapped into, from the material specification or supplier data.', tip: 'For a tapped casting or aluminium part use that material’s strength, not the strength of a steel nut.', effect: 'A weaker tapped material raises J and lengthens the required engagement.', fig: 'stress', sym: 'Su' },
  },
  'bolted-joint': {
    d: { what: 'The nominal (major) diameter of the bolt. It sets the shank area for bolt stiffness and the bearing size used in the member stiffness estimate.', tip: 'Use the thread size, not the hole diameter.', fig: 'diameter', sym: 'd' },
    P: { what: 'The axial distance between thread crests of the bolt, used to work out the tensile stress area of the threaded part.', tip: 'Check whether the bolt is coarse or fine thread; the pitch differs.', fig: 'thread', sym: 'P' },
    grip: { what: 'The total thickness of all parts clamped between the underside of the bolt head and the nut face, including washers.', tip: 'Add washer thickness; leaving it out understates the grip and overstates the stiffness.', fig: 'thickness', sym: 'l' },
    Lt: { what: 'The length of threaded bolt inside the grip; the remainder of the grip is plain shank. The threaded part is more flexible because of its smaller area.', tip: 'It cannot exceed the grip length. For a fully threaded bolt it equals the grip.', effect: 'More thread in the grip lowers bolt stiffness, so the bolt takes a smaller share of the external load.', fig: 'length', sym: 'Lt' },
    Eb: { what: 'The elastic (Young’s) modulus of the bolt material, from the material data sheet or a materials handbook.', tip: 'Enter it in GPa, not MPa.', fig: 'modulus', sym: 'Eb' },
    kmMode: { what: 'How the stiffness of the clamped parts is found: estimated from a 30° pressure cone in one material, or entered from analysis or tests.', tip: 'The estimate suits plain plates of one material; for gaskets, castings or mixed materials enter a value.', fig: 'choice' },
    Em: { what: 'The elastic modulus of the clamped parts, used only by the frustum estimate of member stiffness.', tip: 'Enter it in GPa. Ignored when you enter the member stiffness directly.', effect: 'A stiffer member material raises member stiffness, so the bolt sees less of the external load.', fig: 'modulus', sym: 'Em' },
    km: { what: 'The axial stiffness of the clamped parts together, from finite element analysis or a test. Used only when the member stiffness is set to be entered.', tip: 'Enter kN/mm for the whole clamped stack around one bolt; it is ignored in estimate mode.', effect: 'Higher member stiffness lowers the joint constant, so the bolt load rises less with external load.', fig: 'stiffness', sym: 'km' },
    Fi: { what: 'The clamping force in the bolt after tightening, before the external load is applied, from the torque and preload calculation or a measurement.', tip: 'Enter kilonewtons per bolt; torque-controlled preload scatters widely, so check the lowest likely value.', effect: 'More preload raises both the remaining clamp force and the bolt load one for one.', fig: 'force', sym: 'Fi' },
    Pext: { what: 'The external tensile force that tries to pull this joint apart, as carried by one bolt.', tip: 'Divide the total separating load by the number of bolts sharing it; do not enter the total load.', effect: 'Raises bolt load by C × P and reduces clamp force by (1 − C) × P.', fig: 'force', sym: 'P' },
    Sp: { what: 'The proof strength of the bolt for its property class, used to check the bolt stress under the combined preload and external load.', tip: 'Take it from ISO 898-1 or the supplier for the property class; it is not the tensile strength.', fig: 'stress', sym: 'Sp' },
  },
  'bolt-shear-bearing': {
    F: { what: 'The whole shear load carried by the fastener group, which the tool shares equally between the fasteners.', tip: 'Enter the total load on the group, not the load per bolt. Eccentric loads do not share equally.', effect: 'Shear and bearing stresses rise in proportion.', fig: 'force', sym: 'F' },
    n: { what: 'How many bolts or pins share the load equally in the joint.', tip: 'Count only fasteners that actually carry the load in shear.', effect: 'Both stresses fall in proportion to the number of fasteners.', fig: 'count', sym: 'n' },
    planes: { what: 'How many times each fastener is cut by a shear plane: once in a lap joint, twice in a clevis or a pin between two outer plates.', tip: 'Double shear halves the shear stress but does not change the bearing stress the tool calculates.', fig: 'choice' },
    d: { what: 'The fastener diameter where the shear plane passes: the plain shank, or the thread minor diameter if the thread lies in the shear plane.', tip: 'Use the minor diameter when threads cross the shear plane; the nominal size overstates the shear area.', effect: 'Shear stress falls with the square of diameter; bearing stress falls in proportion.', fig: 'diameter', sym: 'd' },
    t: { what: 'The plate thickness that the fastener bears against: the thinnest plate, or in double shear the smaller of the middle plate and the two outer plates together.', tip: 'Take the governing thickness, not the total stack.', effect: 'Bearing stress falls in proportion to thickness.', fig: 'thickness', sym: 't' },
    tauAllow: { what: 'The shear stress the fastener material may carry in your design, from your design code or standard for that material and grade.', tip: 'Use an allowable value that already includes your code’s safety margin, not the ultimate shear strength.', fig: 'stress', sym: 'τ' },
    bAllow: { what: 'The bearing (crushing) stress the plate material may carry around the hole, from your design code.', tip: 'Use the value for the plate, not the fastener, unless the fastener is the softer material.', fig: 'stress', sym: 'σb' },
  },
  'riveted-joint': {
    p: { what: 'The centre-to-centre spacing of rivets along the seam in one row. The joint strength is worked out for one pitch length.', tip: 'It must be larger than the hole diameter; measure centre to centre, not the gap between holes.', effect: 'A longer pitch raises the tearing strength and the solid plate strength.', fig: 'pitch', sym: 'p' },
    d: { what: 'The diameter of the drilled or punched hole. A driven rivet swells to fill the hole, so this is the diameter that carries shear and bearing.', tip: 'Use the hole diameter, not the rivet shank diameter before driving.', fig: 'diameter', sym: 'd' },
    t: { what: 'The thickness of the thinner plate in the lap joint, which governs tearing and crushing.', tip: 'For unequal plates use the thinner one.', effect: 'Tearing, crushing and solid plate strengths rise in proportion.', fig: 'thickness', sym: 't' },
    rows: { what: 'The number of rivets in one pitch length of the seam, equal to the number of rows when each row has one rivet per pitch.', tip: 'Count the rivets that share the load in one pitch length, not all rivets in the joint.', effect: 'Shearing and crushing strengths rise in proportion.', fig: 'count' },
    shear: { what: 'How many shear planes cut each rivet: one in a lap joint, two in a butt joint with a cover strap on each side.', tip: 'Double shear doubles the rivet shearing strength; it does not change tearing or crushing.', fig: 'choice' },
    st: { what: 'The tensile stress the plate material may carry in your design, from your design code or material data.', tip: 'Use an allowable stress, not the ultimate tensile strength.', fig: 'stress', sym: 'σt' },
    tau: { what: 'The shear stress the rivet material may carry, from your design code or rivet supplier.', tip: 'Use the value for the rivet material, which often differs from the plate.', fig: 'stress', sym: 'τ' },
    sc: { what: 'The crushing (bearing) stress allowed between the rivet and the plate around the hole, from your design code.', tip: 'Use the allowable for the weaker of the rivet and plate materials.', fig: 'stress', sym: 'σc' },
  },
  'tap-drill': {
    system: { what: 'Whether the thread is metric, sized in millimetres with a pitch, or unified, sized in inches with threads per inch. It decides which pitch input is used and the unit of the result.', tip: 'Change the major diameter to match: millimetres for metric, inches for unified.', fig: 'choice' },
    D: { what: 'The basic major diameter of the thread: the nominal size in millimetres for metric threads or in inches for unified threads.', tip: 'The unit follows the thread system: 10 means 10 mm when metric but 10 inches when unified.', fig: 'thread', sym: 'D' },
    pitch: { what: 'The axial distance from one thread crest to the next for a metric thread, from the designation. Ignored for unified threads.', tip: 'A plain designation such as M10 means the coarse pitch; fine threads state the pitch.', effect: 'A coarser pitch needs a smaller drill for the same percentage of thread.', fig: 'thread', sym: 'P' },
    tpi: { what: 'The number of thread crests per inch of length for a unified thread: the number after the dash in the designation. Ignored for metric threads.', tip: 'Do not enter the pitch in inches here; this is a count per inch.', fig: 'thread', sym: 'n' },
    pct: { what: 'How much of the full basic thread depth the hole leaves for the tap to form. Lower percentages mean a larger hole, easier tapping and slightly less thread strength.', tip: 'Type the percentage itself, not a fraction. Choose it from your shop practice for the material and tap.', effect: 'A higher percentage gives a smaller drill size.', fig: 'percent' },
    tap: { what: 'The kind of tap: a cutting tap removes metal to form the thread; a forming (roll) tap displaces metal and needs a larger hole.', tip: 'Forming taps suit ductile materials; check suitability for brittle materials.', fig: 'choice' },
  },
  'metric-thread': {
    d: { what: 'The nominal (basic major) diameter of the ISO metric thread, the number after the M in the designation.', tip: 'Enter the thread size, not the tap drill or clearance hole.', fig: 'thread', sym: 'd' },
    P: { what: 'The axial distance from one thread crest to the next, the number after the × in the designation.', tip: 'A plain designation without a pitch means the coarse series; check the standard pitch for that size.', effect: 'All basic diameters fall by fixed multiples of the pitch, so a coarser pitch reduces them and the stress area.', fig: 'thread', sym: 'P' },
    starts: { what: 'The number of separate thread helices wound side by side. The lead, the axial travel per turn, equals starts times pitch.', tip: 'Ordinary fastener threads are single start. Only the lead and lead angle use this value.', effect: 'More starts increase lead and lead angle in proportion; diameters and stress area do not change.', fig: 'count' },
    Sp: { what: 'The proof stress of the bolt property class, used only to turn the tensile stress area into a proof load.', tip: '0 skips the proof load. Take the value from ISO 898-1 or the supplier.', fig: 'stress', sym: 'Sp' },
  },
  'unified-thread': {
    D: { what: 'The basic major diameter of the unified inch thread in decimal inches: the size before the dash in the designation, written as a decimal.', tip: 'Enter numbered sizes (such as No. 10) as their decimal diameter, and fractions as decimals.', fig: 'thread', sym: 'D' },
    n: { what: 'The number of thread crests per inch of length: the number after the dash in the designation. The pitch is one inch divided by this number.', tip: 'Check the series: UNC and UNF threads of the same size have different counts.', effect: 'More threads per inch give a finer pitch and larger pitch and minor diameters.', fig: 'thread', sym: 'n' },
  },
  'three-wire': {
    angle: { what: 'The included angle between the two flanks of the thread form being measured, which sets the best wire size and the wire constant.', tip: 'Metric and unified are 60°; Acme is 29° and metric trapezoidal is 30°. Use the form on the drawing.', fig: 'choice' },
    P: { what: 'The axial distance from one thread crest to the next, in the same unit as the diameters and wires.', tip: 'Keep every length in one unit; for an inch thread the pitch is 1 ÷ TPI in inches.', fig: 'thread', sym: 'P' },
    E: { what: 'The pitch diameter the thread should have, from the thread limits for its class, often the middle of the tolerance. The tool adds the wire constant to it to give the expected reading.', tip: 'Use the pitch diameter, not the major diameter, and the same unit as the pitch.', effect: 'The expected reading over wires changes one for one with the pitch diameter.', fig: 'thread', sym: 'E' },
    W: { what: 'The measured diameter of the three wires you will actually use. 0 tells the tool to use the best wire size, which touches the flanks at the pitch line.', tip: 'Measure the wires themselves; nominal sizes on the box may differ slightly.', fig: 'diameter', sym: 'W' },
    Mmeas: { what: 'The micrometer reading taken across the three wires on the actual thread, which the tool converts back into a pitch diameter.', tip: '0 means no reading; the pitch diameter from reading is then not reported. Use the same wires as the wire diameter input.', fig: 'length', sym: 'M' },
  },
  'screw-efficiency': {
    d2: { what: 'The pitch (mean) diameter of the screw thread, roughly midway between the major and minor diameters, where the helix angle is measured.', tip: 'Use the pitch diameter, not the outside diameter of the screw.', effect: 'A larger pitch diameter lowers the helix angle, which usually lowers efficiency and makes self-locking more likely.', fig: 'thread', sym: 'd₂' },
    P: { what: 'The axial distance between adjacent thread crests. With the number of starts it gives the lead.', tip: 'On a multi-start screw the pitch is not the lead; enter the crest-to-crest distance.', effect: 'A longer pitch raises the lead and helix angle.', fig: 'thread', sym: 'P' },
    starts: { what: 'The number of separate thread helices on the screw. Lead, the travel per turn, equals starts times pitch.', tip: 'Count the thread ends visible at the end of the screw.', effect: 'More starts raise the helix angle, which usually raises efficiency and makes self-locking less likely.', fig: 'count' },
    flank: { what: 'The thread profile, which sets the flank half-angle used for the friction wedge effect: square, Acme, trapezoidal or V.', tip: 'The options list the included angle; the tool uses half of it.', fig: 'choice' },
    mu: { what: 'The coefficient of friction between the screw and nut threads for the materials and lubrication in service, from supplier data or tests.', tip: 'Friction at start-up is higher than when running; use the condition you are checking.', effect: 'Higher friction lowers efficiency and makes the screw more likely to self-lock.', fig: 'friction', sym: 'μ' },
  },
  'simple-indexing': {
    divisions: { what: 'The number of equal divisions needed around the work in one turn of the spindle, for example the number of gear teeth or slots to cut.', tip: 'Enter the count of divisions, not the angle between them.', fig: 'count', sym: 'N' },
    ratio: { what: 'The number of index crank turns that rotate the dividing head spindle once, set by the head’s worm and wheel.', tip: 'Read it from the head’s plate or manual; do not assume the common value.', effect: 'Crank turns per division rise in proportion.', fig: 'ratio', sym: 'R' },
    plates: { what: 'The set of index plates fitted to your dividing head, which sets the hole circles available for fractional turns.', tip: 'Choose the plates you actually have; the tool searches only their hole circles.', fig: 'choice' },
  },
  'change-gears': {
    cutUnit: { what: 'How the thread to cut is specified: as a pitch in millimetres (metric) or as threads per inch (inch).', tip: 'Match it to the number entered for the thread to cut.', fig: 'choice' },
    cut: { what: 'The thread to be cut on the lathe: its pitch in millimetres, or its threads per inch, according to the unit chosen above.', tip: 'For a multi-start thread the gearing must produce the lead, not the pitch.', fig: 'thread', sym: 'P' },
    screwUnit: { what: 'How the lathe leadscrew is specified: threads per inch or pitch in millimetres, as stamped on the lathe or given in its manual.', tip: 'Imperial lathes usually have TPI leadscrews; check the plate rather than assuming.', fig: 'choice' },
    screw: { what: 'The leadscrew’s threads per inch or pitch in millimetres, according to the unit chosen, from the lathe plate or manual.', tip: 'Measure it if the plate is missing; the result is only as exact as this value.', fig: 'thread' },
    fixed: { what: 'Any fixed gearing inside the headstock before the change gears, given as the number of stud turns per spindle turn (the factor the tool divides the required ratio by).', tip: 'The tool treats this as stud speed ÷ spindle speed: a stud running slower than the spindle needs a value below 1. Use 1 if there is no fixed gearing.', fig: 'ratio' },
    set: { what: 'The range of change gears you have, one of each size, including the 127-tooth gear used for exact metric–inch conversion.', tip: 'Check that every gear in the chosen set is actually in your cabinet before cutting.', fig: 'choice' },
  },
  'helical-gear': {
    mn: { what: 'The normal module: the module measured square to the tooth, equal to the module of the hob or cutter that cuts the gear.', tip: 'Do not enter the transverse module; the tool works it out from the normal module and helix angle.', effect: 'All diameters and the centre distance scale in proportion.', fig: 'pitch', sym: 'mn' },
    beta: { what: 'The angle between the teeth and the gear axis at the pitch diameter. Both gears of an external pair have the same angle, of opposite hand.', tip: '0 gives a spur gear pair, with no overlap ratio.', effect: 'A larger helix angle increases the pitch diameters, centre distance and overlap ratio.', fig: 'angle', sym: 'β' },
    alphan: { what: 'The pressure angle of the tooth profile measured in the normal plane, set by the cutting tool.', tip: 'Use the angle of the hob or rack cutter on the drawing.', fig: 'angle', sym: 'αn' },
    z1: { what: 'The number of teeth on the pinion, the smaller gear of the pair.', tip: 'Count teeth on the actual pinion, not on the mating gear.', effect: 'Raises the pinion pitch diameter and the centre distance in proportion.', fig: 'teeth', sym: 'z₁' },
    z2: { what: 'The number of teeth on the larger gear of the pair.', tip: 'The ratio is gear teeth divided by pinion teeth.', effect: 'Raises the gear pitch diameter, centre distance and ratio.', fig: 'teeth', sym: 'z₂' },
    b: { what: 'The axial width over which the two gears are in mesh. It is used only for the overlap ratio.', tip: 'Use the width in mesh, the narrower of the two gears.', effect: 'The overlap ratio rises in proportion to face width.', fig: 'length', sym: 'b' },
  },
  'gear-forces': {
    kW: { what: 'The power passing through this gear mesh, for example motor power reduced by any upstream losses.', tip: 'Use the power at this mesh, not the installed motor rating if the gear runs below it.', effect: 'All tooth forces rise in proportion to power.', fig: 'power', sym: 'P' },
    rpm: { what: 'The rotational speed of the gear whose pitch diameter you enter, so that power converts into torque on that gear.', tip: 'Pair the speed with the same gear as the diameter; mixing pinion speed and gear diameter gives wrong forces.', effect: 'At constant power, forces fall in proportion as speed rises.', fig: 'rotation', sym: 'n' },
    d: { what: 'The pitch diameter of the same gear, where the tangential force acts. For a helical gear it is the transverse pitch diameter.', tip: 'Use the pitch diameter, not the tip (outside) diameter.', effect: 'Tooth forces fall in proportion as pitch diameter rises.', fig: 'diameter', sym: 'd' },
    alphan: { what: 'The pressure angle of the tooth profile in the normal plane, which sets how much of the tooth force pushes the gears apart radially.', tip: 'Use the angle on the gear drawing.', effect: 'A larger pressure angle raises the radial force; the tangential force does not change.', fig: 'angle', sym: 'αn' },
    beta: { what: 'The angle of the teeth to the gear axis at the pitch diameter. Helical teeth create an axial thrust that the bearings must carry.', tip: '0 means spur teeth and no axial force.', effect: 'A larger helix angle raises the axial and radial forces.', fig: 'angle', sym: 'β' },
  },
  'lewis-bending': {
    Ft: { what: 'The force acting tangentially at the pitch circle that bends the tooth, from the transmitted torque and the pitch diameter.', tip: 'Work it out with the gear tooth forces tool for the same gear and speed.', effect: 'Bending stress rises in proportion.', fig: 'force', sym: 'Ft' },
    m: { what: 'The module of the gear: pitch diameter divided by the number of teeth, which sets the tooth size.', tip: 'Enter the module, not the diametral pitch; convert inch gears first.', effect: 'Bending stress falls in proportion as module rises.', fig: 'pitch', sym: 'm' },
    b: { what: 'The axial width of the tooth that is in contact with the mating gear.', tip: 'Use the width actually in mesh, not the blank width of a wider gear.', effect: 'Bending stress falls in proportion as face width rises.', fig: 'length', sym: 'b' },
    Y: { what: 'The Lewis form factor, a dimensionless number describing the tooth’s bending strength for its tooth count and pressure angle, from a form factor table.', tip: 'Take Y from a table for the module form of the Lewis equation that the method uses; factors defined for other forms of the equation give different numbers.', effect: 'Bending stress falls in proportion as Y rises.', fig: 'factor', sym: 'Y' },
    d: { what: 'The pitch diameter of the gear, used with the speed to find the pitch-line velocity for the velocity factor.', tip: 'Use the pitch diameter of the gear whose speed you enter.', fig: 'diameter', sym: 'd' },
    rpm: { what: 'The rotational speed of the same gear, used to find the pitch-line velocity that sets the velocity factor.', tip: 'Use the running speed of this gear, not of the mating gear.', effect: 'Higher speed raises the velocity factor and the bending stress.', fig: 'rotation', sym: 'n' },
    make: { what: 'How the teeth are produced, which chooses the Barth velocity factor allowing for dynamic loading from tooth errors.', tip: 'Pick the final finishing method of the teeth, not the roughing method.', fig: 'choice' },
    allow: { what: 'The bending stress the gear material may carry in this application, for its material and heat treatment, from your design data or gear standard.', tip: 'Use a design allowable that already includes your safety margin.', fig: 'stress', sym: 'σa' },
  },
  'worm-gear': {
    mx: { what: 'The axial module of the worm, equal to the transverse module of the wheel. Times π it gives the worm’s axial pitch.', tip: 'Do not use the normal module of the worm thread here.', fig: 'pitch', sym: 'mx' },
    z1: { what: 'The number of thread starts on the worm, which with the wheel teeth sets the ratio.', tip: 'Count the separate thread ends at the end of the worm.', effect: 'More starts lower the ratio and raise lead angle and efficiency; self-locking becomes less likely.', fig: 'count', sym: 'z₁' },
    z2: { what: 'The number of teeth on the worm wheel. Ratio equals wheel teeth divided by worm starts.', tip: 'Count teeth on the wheel, not threads on the worm.', effect: 'Raises the ratio, wheel diameter and centre distance.', fig: 'teeth', sym: 'z₂' },
    d1: { what: 'The pitch diameter of the worm, where the lead angle is measured and the wheel meshes.', tip: 'Use the pitch diameter, not the outside diameter of the worm.', effect: 'A larger worm diameter lowers the lead angle and the efficiency.', fig: 'diameter', sym: 'd₁' },
    alphan: { what: 'The pressure angle of the worm thread in the normal plane, from the worm drawing or the gear maker.', tip: 'Use the normal angle, not the axial angle, if the drawing gives both.', fig: 'angle', sym: 'αn' },
    mu: { what: 'The friction coefficient between the worm and wheel at the running sliding speed and lubrication, from the gear maker.', tip: 'Friction is higher at start-up than at running speed, so starting efficiency is lower.', effect: 'Higher friction lowers efficiency in both directions and makes self-locking more likely.', fig: 'friction', sym: 'μ' },
  },
  'bevel-gear': {
    m: { what: 'The transverse module measured at the outer (heel) end of the teeth, where bevel gear sizes are specified.', tip: 'Use the module at the large end, not the mean module at mid-face.', effect: 'Diameters and cone distance scale in proportion.', fig: 'pitch', sym: 'm' },
    z1: { what: 'The number of teeth on the pinion, the smaller bevel gear.', tip: 'Count the pinion teeth, not the gear teeth.', fig: 'teeth', sym: 'z₁' },
    z2: { what: 'The number of teeth on the larger bevel gear.', tip: 'Ratio and pitch cone angles follow from both tooth counts.', fig: 'teeth', sym: 'z₂' },
    shaft: { what: 'The angle between the two shaft axes where they intersect, which with the tooth counts sets the pitch cone angles.', tip: 'Measure between the axes, not between the gear faces.', fig: 'angle', sym: 'Σ' },
    b: { what: 'The length of the teeth measured along the pitch cone. It is used only to compare with the cone distance.', tip: 'Measure along the tooth, not the axial width of the blank.', fig: 'length', sym: 'b' },
  },
  'chordal-tooth': {
    m: { what: 'The module of the gear: pitch diameter divided by the number of teeth.', tip: 'For a helical gear checked in the normal plane, use consistent normal values throughout.', fig: 'pitch', sym: 'm' },
    z: { what: 'The number of teeth on the gear being measured.', tip: 'Count all teeth on the gear, not only those spanned by the caliper.', fig: 'teeth', sym: 'z' },
    a: { what: 'The radial height of the tooth from the pitch circle to the tip. 0 uses the standard addendum of one module.', tip: 'Enter the actual addendum for shifted or stub teeth; the standard value would set the caliper depth wrongly.', effect: 'The chordal addendum, the caliper depth setting, changes one for one with it.', fig: 'height', sym: 'a' },
    t: { what: 'The tooth thickness measured along the pitch circle arc. 0 uses the standard thickness, half the circular pitch.', tip: 'Enter a thinned value to include the backlash allowance from the drawing.', effect: 'A larger arc thickness gives a larger chordal thickness.', fig: 'thickness', sym: 't' },
  },
  'span-measurement': {
    mn: { what: 'The normal module of the gear, equal to the module of the cutting tool.', tip: 'For a helical gear do not use the transverse module.', effect: 'The base tangent length scales in proportion.', fig: 'pitch', sym: 'mn' },
    z: { what: 'The number of teeth on the gear being measured.', tip: 'Count the whole gear, not just the teeth spanned.', fig: 'teeth', sym: 'z' },
    alphan: { what: 'The pressure angle of the tooth profile in the normal plane, set by the cutting tool.', tip: 'Use the angle on the gear drawing.', fig: 'angle', sym: 'αn' },
    beta: { what: 'The angle of the teeth to the gear axis at the pitch circle. It changes the transverse pressure angle and the face width needed for the anvils.', tip: '0 means a spur gear; the face width check is then skipped.', fig: 'angle', sym: 'β' },
    x: { what: 'The profile shift coefficient: how far the cutter was moved out (positive) or in (negative) from standard, as a multiple of the module.', tip: 'Take it from the gear drawing; 0 means an unshifted gear. Enter the coefficient, not the shift in millimetres.', effect: 'For the same number of teeth spanned, a positive shift increases the base tangent length.', fig: 'factor', sym: 'x' },
    k: { what: 'How many teeth the disc micrometer anvils span. 0 lets the tool choose the usual number, so the anvils touch near the pitch circle.', tip: 'If you enter your own number, check that the anvils touch the flanks, not the tips or roots.', effect: 'Each extra tooth spanned adds one base pitch to the length.', fig: 'teeth', sym: 'k' },
    b: { what: 'The axial width of the gear teeth, used only on helical gears to check that the anvils fit across the face.', tip: 'Ignored for spur gears.', fig: 'length', sym: 'b' },
  },
  'gear-over-pins': {
    m: { what: 'The module of the spur gear: pitch diameter divided by the number of teeth.', tip: 'Do not enter diametral pitch; convert it to a module first.', fig: 'pitch', sym: 'm' },
    z: { what: 'The number of teeth on the gear. Even counts put the pins exactly opposite; odd counts put them nearly opposite.', tip: 'Count every tooth; the formula changes between even and odd counts.', fig: 'teeth', sym: 'z' },
    alpha: { what: 'The pressure angle of the tooth profile at the pitch circle, from the gear drawing.', tip: 'Use the angle of the cutter on the drawing.', fig: 'angle', sym: 'α' },
    x: { what: 'The profile shift coefficient from the gear drawing, as a multiple of the module; it thickens or thins the teeth.', tip: '0 means an unshifted gear. Enter the coefficient, not the shift in millimetres.', effect: 'A positive shift thickens the teeth and increases the measurement over pins.', fig: 'factor', sym: 'x' },
    thin: { what: 'The amount the arc tooth thickness at the pitch circle is reduced to give backlash, from the gear drawing.', tip: 'Enter the reduction of arc thickness, not of the measurement over pins.', effect: 'More thinning reduces the measurement over pins.', fig: 'gap' },
    dp: { what: 'The actual diameter of the pins or balls placed in opposite tooth spaces. 0 lets the tool use a size that touches near the pitch circle.', tip: 'Measure the pins you will use; any difference from the entered value changes the reading.', fig: 'diameter', sym: 'dp' },
  },
  'gear-train': {
    nin: { what: 'The rotational speed of the first driving gear, at the input shaft of the train.', tip: 'Use the speed of the first driver, not of the motor if there is a belt or coupling ratio in between.', effect: 'Output speed changes in proportion.', fig: 'rotation', sym: 'n' },
    Tin: { what: 'The torque delivered to the first driving gear at the input shaft.', tip: 'Use the torque at the gear shaft, after any belt or coupling ratio upstream.', effect: 'Output torque changes in proportion.', fig: 'torque', sym: 'T' },
    eff: { what: 'The efficiency of each single gear mesh in the train; the tool applies it once for every mesh in use.', tip: 'Enter the efficiency per mesh, not the overall train efficiency. Type the percentage, not a fraction.', effect: 'Overall efficiency is this value raised to the number of meshes, so it lowers output torque.', fig: 'efficiency', sym: 'η' },
    a1: { what: 'The number of teeth on the driving gear of the first mesh, on the input shaft.', tip: 'A mesh is used only when both its driver and driven teeth are above 0.', effect: 'More driver teeth lower the ratio and raise output speed.', fig: 'teeth' },
    b1: { what: 'The number of teeth on the driven gear of the first mesh.', tip: 'The mesh ratio is driven teeth divided by driver teeth.', effect: 'More driven teeth raise the ratio and output torque and lower output speed.', fig: 'teeth' },
    a2: { what: 'The number of teeth on the driving gear of the second mesh, on the same shaft as the first driven gear.', tip: '0 leaves this mesh out of the train.', effect: 'More driver teeth lower the ratio and raise output speed.', fig: 'teeth' },
    b2: { what: 'The number of teeth on the driven gear of the second mesh.', tip: '0 leaves this mesh out of the train.', effect: 'More driven teeth raise the ratio and output torque and lower output speed.', fig: 'teeth' },
    a3: { what: 'The number of teeth on the driving gear of the third mesh, on the same shaft as the second driven gear.', tip: '0 leaves this mesh out of the train.', effect: 'More driver teeth lower the ratio and raise output speed.', fig: 'teeth' },
    b3: { what: 'The number of teeth on the driven gear of the third mesh.', tip: '0 leaves this mesh out of the train.', effect: 'More driven teeth raise the ratio and output torque and lower output speed.', fig: 'teeth' },
    a4: { what: 'The number of teeth on the driving gear of the fourth mesh, on the same shaft as the third driven gear.', tip: '0 leaves this mesh out of the train.', effect: 'More driver teeth lower the ratio and raise output speed.', fig: 'teeth' },
    b4: { what: 'The number of teeth on the driven gear of the fourth mesh.', tip: '0 leaves this mesh out of the train.', effect: 'More driven teeth raise the ratio and output torque and lower output speed.', fig: 'teeth' },
  },
  'cam-motion': {
    law: { what: 'The mathematical shape of the follower motion during the rise, which sets the peak velocity and acceleration coefficients.', tip: 'Simple harmonic and constant acceleration have acceleration jumps at the ends of the rise; cycloidal and 3-4-5 polynomial do not.', fig: 'choice' },
    h: { what: 'The total distance the follower moves during the rise, from its lowest to its highest position.', tip: 'Use the follower lift, not the cam radius difference if a rocker arm changes the ratio.', effect: 'Peak velocity, acceleration and inertia force rise in proportion.', fig: 'height', sym: 'h' },
    beta: { what: 'The angle the cam turns through while the follower completes the rise.', tip: 'Enter the rise angle only, not the whole rise, dwell and return cycle.', effect: 'Acceleration falls with the square of this angle, so a longer rise angle greatly lowers it.', fig: 'angle', sym: 'β' },
    rpm: { what: 'The rotational speed of the camshaft.', tip: 'Use the camshaft speed, which may differ from the motor or crankshaft speed.', effect: 'Acceleration and inertia force rise with the square of speed.', fig: 'rotation', sym: 'n' },
    mass: { what: 'The mass of the follower and every part that moves with it during the rise, such as push rods, tappets and tooling.', tip: 'Include a share of the return spring mass if your method calls for it.', effect: 'Peak inertia force rises in proportion; velocity and acceleration do not change.', fig: 'mass', sym: 'm' },
  },
  'belt-drive-tensions': {
    kW: { what: 'The power the belt must transmit on this pulley, normally the motor power multiplied by your service factor.', tip: 'Use the design power including service factor if you are sizing; use actual power to estimate running tensions.', effect: 'Effective pull and both tensions rise in proportion.', fig: 'power', sym: 'P' },
    d: { what: 'The pitch diameter of the pulley being checked, usually the smaller one, where the belt pitch line runs.', tip: 'Use the pitch diameter, not the outside diameter of a V-belt pulley.', effect: 'A larger pulley raises belt speed, so effective pull falls.', fig: 'diameter', sym: 'd' },
    rpm: { what: 'The rotational speed of the same pulley whose diameter you entered.', tip: 'Pair the speed and diameter of the same pulley.', effect: 'Higher speed lowers effective pull but raises centrifugal tension.', fig: 'rotation', sym: 'n' },
    wrap: { what: 'The arc over which the belt touches this pulley, measured around the pulley centre.', tip: 'The smaller pulley has the smaller wrap and normally governs slip.', effect: 'More wrap reduces the tensions needed to carry the power without slipping.', fig: 'angle', sym: 'θ' },
    mu: { what: 'The friction coefficient between the belt and the pulley surface, from the belt maker.', tip: 'For V-belts enter the plain friction coefficient; the tool adds the wedge effect of the groove itself.', effect: 'Higher friction lowers the tensions needed to avoid slip.', fig: 'friction', sym: 'μ' },
    groove: { what: 'The included angle of the V-groove in the pulley, which wedges the belt and raises the effective friction. 0 means a flat belt.', tip: 'Enter the full included angle, not the half-angle.', effect: 'A narrower groove raises the effective friction and lowers the required tensions.', fig: 'angle', sym: 'β' },
    mass: { what: 'The mass of one metre of belt, for all belts together on a multi-belt drive, from the belt data sheet. It gives the centrifugal tension.', tip: 'For several belts multiply the single-belt mass by the number of belts.', effect: 'Centrifugal tension rises in proportion and adds to both belt tensions.', fig: 'mass', sym: 'm' },
  },
  'chain-length': {
    p: { what: 'The distance between the centres of adjacent chain rollers, from the chain designation or catalogue.', tip: 'Check the chain standard: ISO and ANSI chains of similar size can differ in pitch.', fig: 'pitch', sym: 'p' },
    z1: { what: 'The number of teeth on the smaller sprocket.', tip: 'Count teeth on the small sprocket, usually the driver.', fig: 'teeth', sym: 'z₁' },
    z2: { what: 'The number of teeth on the larger sprocket.', tip: 'Count teeth on the large sprocket.', fig: 'teeth', sym: 'z₂' },
    C: { what: 'The centre distance between the two sprocket shafts that you would like. The tool rounds the chain to an even number of links and returns the exact centre distance.', tip: 'Allow adjustment in the mounting; the exact centre distance will differ slightly from this value.', effect: 'A longer centre distance needs more links.', fig: 'length', sym: 'C' },
    rpm: { what: 'The rotational speed of the small sprocket, used only to work out chain speed.', tip: 'Use the speed of the small sprocket, not the large one.', effect: 'Chain speed rises in proportion; chain length is unchanged.', fig: 'rotation', sym: 'n' },
  },
  'reflected-inertia': {
    JL: { what: 'The mass moment of inertia of everything on the load side, taken about the load shaft: tables, rolls, couplings and payload.', tip: 'Enter inertia in kg·m², not mass or weight; convert from kg·cm² if a catalogue uses that.', effect: 'Reflected inertia rises in proportion and falls with the square of the ratio.', fig: 'inertia', sym: 'JL' },
    Jm: { what: 'The inertia of the motor rotor from the motor data sheet, plus the gearbox input inertia if there is one.', tip: 'Data sheets often list kg·cm²; divide by 10 000 to get kg·m².', effect: 'A larger rotor inertia lowers the inertia ratio but adds to the acceleration torque.', fig: 'inertia', sym: 'Jm' },
    i: { what: 'The speed reduction between motor and load: motor speed divided by load speed.', tip: 'Enter it as a reduction greater than 1 for a gearbox that slows the load.', effect: 'Reflected inertia falls with the square of the ratio, and load torque at the motor falls in proportion.', fig: 'ratio', sym: 'i' },
    eff: { what: 'The efficiency of the gearbox between motor and load, from the gearbox maker.', tip: 'Type the percentage itself, not a fraction.', effect: 'Lower efficiency raises the reflected inertia and the load torque seen by the motor.', fig: 'efficiency', sym: 'η' },
    nL: { what: 'The speed the load shaft must reach at the end of the acceleration, starting from rest.', tip: 'Enter load speed, not motor speed; the tool multiplies by the ratio.', effect: 'Acceleration torque rises in proportion.', fig: 'rotation', sym: 'nL' },
    t: { what: 'The time allowed to accelerate the load from rest to the target speed, at constant acceleration.', tip: 'Enter seconds, not milliseconds.', effect: 'Acceleration torque falls in proportion as the time is lengthened.', fig: 'time', sym: 't' },
    TL: { what: 'The steady torque the load needs at the load shaft from friction, gravity or the process, apart from accelerating inertia.', tip: 'Take it at the load shaft; the tool reflects it to the motor through the ratio and efficiency.', effect: 'Adds to the peak motor torque after dividing by ratio and efficiency.', fig: 'torque', sym: 'TL' },
  },
  'ballscrew-limits': {
    dr: { what: 'The root (minor) diameter of the screw shaft at the bottom of the ball groove, from the screw catalogue. The tool treats the shaft as a plain rod of this diameter.', tip: 'Use the root diameter, not the nominal screw diameter.', effect: 'Critical speed rises in proportion and buckling load with the fourth power of this diameter.', fig: 'diameter', sym: 'dr' },
    L: { what: 'The unsupported length of the screw: between the bearings, or from the bearing to the nut at its furthest position, whichever governs the case being checked.', tip: 'Use the worst case, the longest unsupported span in service.', effect: 'Critical speed and buckling load both fall with the square of length.', fig: 'length', sym: 'L' },
    ends: { what: 'How the screw ends are held by bearings: fixed means a bearing pair that resists bending; supported means a single bearing that allows rotation; free means unsupported.', tip: 'Choose what the mounting really provides; a single radial bearing is supported, not fixed.', fig: 'choice' },
    E: { what: 'The elastic modulus of the screw shaft material, from the material data sheet or screw maker.', tip: 'Enter it in GPa, not MPa.', fig: 'modulus', sym: 'E' },
    rho: { what: 'The density of the screw shaft material, from the material data sheet.', tip: 'Enter kilograms per cubic metre, not grams per cubic centimetre.', effect: 'A denser material lowers the critical speed; buckling load is unaffected.', fig: 'density', sym: 'ρ' },
    rpm: { what: 'The highest speed the screw turns in service, compared with the allowed share of critical speed.', tip: 'Use the screw speed in rapid traverse, not the motor speed if there is a belt ratio.', fig: 'rotation', sym: 'n' },
    Fa: { what: 'The largest axial force that pushes on the screw in compression, compared with the allowed share of buckling load.', tip: 'Include acceleration and process forces; tension loads do not cause buckling.', fig: 'force', sym: 'Fa' },
    speedPct: { what: 'The highest share of the calculated critical speed you allow in service, from your design rule or the screw maker.', tip: 'Type the percentage itself, not a fraction.', effect: 'Sets the allowed speed line; the critical speed does not change.', fig: 'percent' },
    loadPct: { what: 'The highest share of the calculated buckling load you allow in service, from your design rule or the screw maker.', tip: 'Type the percentage itself, not a fraction.', effect: 'Sets the allowed load line; the buckling load does not change.', fig: 'percent' },
  },
  'clutch-torque': {
    Do: { what: 'The outside diameter of the annular friction lining or pad contact area.', tip: 'Use the lining diameter, not the plate or disc outer diameter if the lining is smaller.', effect: 'A larger outer diameter raises the mean radius and the torque capacity.', fig: 'diameter', sym: 'Do' },
    Di: { what: 'The inside diameter of the annular friction lining, which must be smaller than the outer diameter.', tip: 'Use the inner edge of the friction material, not the hub or spline diameter.', fig: 'diameter', sym: 'Di' },
    surfaces: { what: 'The number of friction interfaces that carry torque. A single plate clamped between a flywheel and a pressure plate has two.', tip: 'Count interfaces, not plates; each plate faced on both sides gives two.', effect: 'Torque capacity rises in proportion.', fig: 'count', sym: 'n' },
    mu: { what: 'The dynamic friction coefficient of the lining against its mating surface, from the lining maker.', tip: 'Use a conservative value; friction falls with heat, wear and contamination.', effect: 'Torque capacity rises in proportion.', fig: 'friction', sym: 'μ' },
    F: { what: 'The axial force pressing the friction surfaces together, from the springs or the actuator.', tip: 'Use the force with a worn lining if spring force falls with wear.', effect: 'Torque capacity and peak lining pressure rise in proportion.', fig: 'force', sym: 'F' },
    Treq: { what: 'The torque the clutch or brake must transmit, already multiplied by your service factor.', tip: 'Apply the service factor before entering the value; the tool compares capacity with it directly.', effect: 'Moves the pass or fail line only; the torque capacity does not change.', fig: 'torque', sym: 'T' },
  },
  'motor-power': {
    mode: { what: 'Which way the relation is solved: line current from a required shaft power, or shaft power from a measured line current.', tip: 'In current mode the measured current is ignored; in power mode the shaft power input is ignored.', fig: 'choice' },
    V: { what: 'The voltage between any two of the three supply lines (line-to-line) at the motor terminals.', tip: 'Use the line-to-line voltage, not the line-to-neutral (phase) voltage.', effect: 'At a given power, current falls in proportion as voltage rises.', fig: 'electric', sym: 'V' },
    kW: { what: 'The mechanical power delivered at the motor shaft, rated or required. Used only in current mode.', tip: 'This is output power; the tool divides by efficiency to find input power.', effect: 'Line current rises in proportion.', fig: 'power', sym: 'P' },
    I: { what: 'The current measured in one supply line with the motor running at the load of interest. Used only in power mode.', tip: 'Measure with a clamp meter on one line conductor at a steady load.', effect: 'Input and output power rise in proportion.', fig: 'electric', sym: 'I' },
    pf: { what: 'The power factor of the motor at this load: the ratio of real power to apparent power, from the motor data sheet.', tip: 'It falls at part load; use the value for the actual load, not the full-load nameplate value.', effect: 'A lower power factor raises current for the same power.', fig: 'factor', sym: 'pf' },
    eff: { what: 'The motor efficiency at this load: shaft output power as a share of electrical input power, from the motor data sheet.', tip: 'Type the percentage itself, not a fraction.', effect: 'Lower efficiency raises current for the same shaft power.', fig: 'efficiency', sym: 'η' },
    rpm: { what: 'The speed of the motor shaft, used only to convert output power into shaft torque.', tip: 'Use the loaded (rated) speed, not the synchronous speed.', effect: 'At constant power, torque falls in proportion as speed rises.', fig: 'rotation', sym: 'n' },
  },
  'key-stress': {
    T: { what: 'The peak torque the key must transmit between the shaft and the hub, including your service factor.', tip: 'Enter the torque at this key, in newton metres, with the service factor already applied.', effect: 'Shear and crushing stresses rise in proportion.', fig: 'torque', sym: 'T' },
    d: { what: 'The shaft diameter at the keyway. The torque divided by half this diameter gives the force on the key.', tip: 'Use the shaft diameter at the key seat, not at a shoulder.', effect: 'A larger shaft lowers the key force and both stresses in proportion.', fig: 'diameter', sym: 'd' },
    w: { what: 'The width of the parallel key across the shaft, from the key standard for this shaft size.', tip: 'Use the key width, not the keyway depth.', effect: 'Shear stress falls in proportion; crushing stress is unaffected.', fig: 'length', sym: 'w' },
    h: { what: 'The height of the key in the radial direction. The tool assumes half of it bears against the hub.', tip: 'Enter the full key height; the tool halves it.', effect: 'Crushing stress falls in proportion; shear stress is unaffected.', fig: 'height', sym: 'h' },
    L: { what: 'The straight-sided length of key in contact with both shaft and hub that actually carries load.', tip: 'Subtract rounded ends, and do not count length beyond the hub.', effect: 'Both stresses fall in proportion as length rises.', fig: 'length', sym: 'L' },
    tauA: { what: 'The shear stress the key material may carry in your design, from your design data or code.', tip: 'Use an allowable that includes your safety margin, not the ultimate shear strength.', fig: 'stress', sym: 'τa' },
    sigA: { what: 'The compressive (crushing) stress allowed on the key sides, taken for the weakest of the key, shaft and hub materials.', tip: 'A soft hub material, such as cast iron or aluminium, often governs.', fig: 'stress', sym: 'σa' },
  },
  'bearing-life-adjusted': {
    type: { what: 'Whether the bearing has balls or rollers, which sets the life exponent in the rating life equation.', tip: 'Needle and tapered roller bearings count as roller bearings.', fig: 'choice' },
    C: { what: 'The basic dynamic load rating of the bearing from the maker’s catalogue: the load that gives a basic rating life of one million revolutions.', tip: 'Use the dynamic rating C, not the static rating C₀.', effect: 'Life rises with the cube of C for ball bearings and the 10/3 power for roller bearings.', fig: 'force', sym: 'C' },
    Fr: { what: 'The load acting on the bearing at right angles to the shaft, from a shaft reaction calculation.', tip: 'Enter the load on this bearing, not the total load on the shaft.', fig: 'force', sym: 'Fr' },
    Fa: { what: 'The load acting on the bearing along the shaft axis, such as gear thrust or preload.', tip: 'Use the thrust on this bearing only; enter 0 for a purely radial load.', fig: 'force', sym: 'Fa' },
    X: { what: 'The radial load factor used to combine radial and axial loads into an equivalent load, from the catalogue for this bearing and its Fa/Fr ratio.', tip: 'Use the catalogue value for the actual Fa/Fr ratio; for pure radial load it is 1.', fig: 'factor', sym: 'X' },
    Y: { what: 'The axial load factor used to combine radial and axial loads into an equivalent load, from the catalogue for this bearing.', tip: 'Use the catalogue value for the actual Fa/Fr ratio; for pure radial load it is 0.', fig: 'factor', sym: 'Y' },
    rpm: { what: 'The rotational speed of the bearing, which converts life in revolutions into hours.', tip: 'For variable duty use a time-weighted mean speed.', effect: 'Life in hours falls in proportion as speed rises.', fig: 'rotation', sym: 'n' },
    rel: { what: 'The reliability the life must achieve: the share of identical bearings expected to reach the calculated life. It selects the reliability factor a₁.', tip: 'Higher reliability gives a shorter life for the same bearing.', fig: 'choice' },
    aiso: { what: 'The life modification factor for lubrication, contamination and fatigue load limit, from the bearing maker’s method.', tip: 'Use 1 only if it has not been assessed; work it out with the maker’s method for the lubricant and cleanliness.', effect: 'Adjusted life changes in direct proportion.', fig: 'factor', sym: 'aISO' },
    req: { what: 'The service life the bearing must reach in operating hours, from the machine specification or customer requirement.', tip: 'Count running hours, not calendar time.', effect: 'Moves the pass or fail line only; the calculated life does not change.', fig: 'time' },
  },
  'journal-bearing-pv': {
    W: { what: 'The radial force carried by the plain bearing, from a shaft reaction calculation.', tip: 'Enter the load on this bearing, not the total shaft load.', effect: 'Pressure and PV rise in proportion.', fig: 'force', sym: 'W' },
    d: { what: 'The diameter of the shaft (journal) running in the bearing.', tip: 'Use the shaft diameter at the bearing, not the bearing outside diameter.', effect: 'A larger shaft lowers pressure but raises sliding speed.', fig: 'diameter', sym: 'd' },
    L: { what: 'The axial length of the bearing surface in contact with the shaft.', tip: 'Subtract chamfers and oil grooves that carry no load.', effect: 'Pressure and PV fall in proportion; sliding speed is unchanged.', fig: 'length', sym: 'L' },
    rpm: { what: 'The rotational speed of the shaft. For oscillating motion, the equivalent continuous speed from the bearing maker’s method.', tip: 'For oscillation do not enter the cycle rate; convert it with the maker’s method.', effect: 'Sliding speed and PV rise in proportion.', fig: 'rotation', sym: 'n' },
    Pmax: { what: 'The highest projected pressure the bearing material allows, from the bearing material maker.', tip: 'Check whether the maker gives a static or a dynamic limit and use the one that matches the duty.', fig: 'pressure', sym: 'Pmax' },
    Vmax: { what: 'The highest sliding speed the bearing material allows, from the maker, for the lubrication condition.', tip: 'Dry-running and lubricated limits differ; use the one that applies.', fig: 'velocity', sym: 'Vmax' },
    PVmax: { what: 'The highest product of pressure and sliding speed the bearing material allows, from the maker, which limits heating.', tip: 'Use the PV limit for the actual lubrication condition.', fig: 'number', sym: 'PVmax' },
  },
  'o-ring-gland': {
    gland: { what: 'Where the groove is: in a piston or male part, so the ring is stretched onto the groove bottom, or in a bore for a rod, so the ring is compressed around its circumference.', tip: 'The groove diameter input changes meaning with this choice.', fig: 'choice' },
    duty: { what: 'Whether the seal is static or moves (reciprocating). It changes only the squeeze range the result is checked against.', tip: 'Choose dynamic for any seal that slides in service.', fig: 'choice' },
    id: { what: 'The inside diameter of the O-ring as made, from the size standard or the supplier’s size list.', tip: 'Use the ring inside diameter, not the groove or shaft diameter.', effect: 'For a piston groove, a smaller ring diameter means more stretch and a thinner cross-section.', fig: 'diameter', sym: 'ID' },
    cs: { what: 'The cross-section diameter of the O-ring cord, from the size standard.', tip: 'Measure the cord thickness, not the radial width of the fitted ring in its groove.', effect: 'A thicker cross-section raises squeeze and gland fill.', fig: 'diameter', sym: 'CS' },
    gd: { what: 'The groove diameter: the groove bottom diameter for a piston groove, or the groove outer diameter for a rod (bore) groove.', tip: 'Measure the diameter that matches the groove location selected above.', fig: 'diameter', sym: 'gd' },
    depth: { what: 'The radial distance from the groove bottom to the mating surface at nominal clearance; the space the ring cross-section is squeezed into.', tip: 'Include the radial clearance gap to the mating part, not just the machined groove depth.', effect: 'A shallower gland raises squeeze and gland fill.', fig: 'depth', sym: 'h' },
    width: { what: 'The axial width of the groove, which with the depth sets the space available for the ring.', tip: 'Allow room for fluid swell; a narrow groove raises fill.', effect: 'A wider groove lowers gland fill; squeeze does not change.', fig: 'length', sym: 'b' },
  },
});
